--- api/verificacoes/certificados.spec.js	
+++ api/verificacoes/certificados.spec.js	
@@ -0,0 +1,162 @@
+import test from 'node:test';
+import assert from 'node:assert/strict';
+import { criarServidor } from '../servidor.js';
+
+test('certificado: atividade inexistente retorna 422', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_nao_existente/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 422);
+    const body = await res.json();
+    assert.equal(body.erro, 'ATIVIDADE_NAO_ENCERRADA'); 
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: atividade cancelada retorna 422', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+    await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/cancelamento`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'org-ana' }
+    });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 422);
+    const body = await res.json();
+    assert.equal(body.erro, 'ATIVIDADE_CANCELADA');
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: participante nao inscrito retorna 403', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 403);
+    const body = await res.json();
+    assert.equal(body.erro, 'NAO_INSCRITO');
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: atividade nao encerrada retorna 422', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 422);
+    const body = await res.json();
+    assert.equal(body.erro, 'ATIVIDADE_NAO_ENCERRADA');
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: frequencia insuficiente (< 75%) retorna 422', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 422);
+    const body = await res.json();
+    assert.equal(body.erro, 'PRESENCA_INSUFICIENTE');
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: emissao bem-sucedida retorna 201', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 201);
+    const body = await res.json();
+    assert.ok(body.codigo);
+    assert.equal(body.atividadeId, 'atv_1a2b3c4d');
+    assert.equal(body.participanteId, 'p-carla');
+    assert.equal(body.cargaHorariaMinutos, 360);
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: reemissao retorna 200 com mesmo certificado', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res1 = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+    const body1 = await res1.json();
+
+    const res2 = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+    const body2 = await res2.json();
+
+    assert.equal(res2.status, 200);
+    assert.equal(body2.codigo, body1.codigo);
+  } finally {
+    await servidor.fechar();
+  }
+});
+
+test('certificado: carga horaria e frequencia basica', async () => {
+  const servidor = await criarServidor({ porta: 0 });
+  try {
+    await fetch(`http://localhost:${servidor.porta}/_teste/reset`, { method: 'POST' });
+
+    const res = await fetch(`http://localhost:${servidor.porta}/atividades/atv_1a2b3c4d/certificado`, {
+      method: 'POST',
+      headers: { 'X-Usuario': 'p-carla' }
+    });
+
+    assert.equal(res.status, 201);
+    const body = await res.json();
+    assert.equal(body.cargaHorariaMinutos, 360);
+    assert.equal(body.presencas, 2);
+    assert.equal(body.encontros, 2);
+  } finally {
+    await servidor.fechar();
+  }
+});
\ No newline at end of file

